<script setup lang="ts">import { computed } from 'vue'; import { competitionStatus } from '../utils/ui'; const p=defineProps<{ status?: string; label?: string }>(); const tone=computed(()=>['RUNNING','ACTIVE','APPROVED','PUBLISHED','ON_SALE'].includes(p.status||'')?'success':['CANCELLED','REJECTED','SOLD'].includes(p.status||'')?'muted':['REGISTRATION','RESULT_CONFIRMING','PENDING'].includes(p.status||'')?'accent':'neutral')</script>
<template><text :class="['status-badge', tone]">{{ label || competitionStatus(status) }}</text></template>
<style scoped>.status-badge{display:inline-flex;min-height:1.5rem;align-items:center;padding:0 .55rem;border-radius:999px;color:#58615d;background:#eff1f0;font-size:.6875rem;font-weight:700}.success{color:#2f6a52;background:#edf6f1}.accent{color:#856816;background:#faf3d7}.muted{color:#737b77;background:#eceeed}.neutral{color:#365148;background:#eef3f0}</style>
